class ExecutedOrder(Packet):
    name = 'ExecutedOrder'
    fields_desc = [
    CharEnumField("msgType", OutMsgType.ExecutedOrder, OutMsgType),
    u64("timestamp", 0),
    u32("userRef", 0),
    u32("qty", 0),
    Price("price", 0x7FFFFFFF),
    CharEnumField("liqFlag", LiqFlag.Continuous, LiqFlag),
    u32("matchNum", 0),
    string4("contraFirm", ""),
    CharEnumField("tradingMode", TradingMode.OpeningAuction, TradingMode),
    CharEnumField("transCat", TransactionCategory.DarkTrade, TransactionCategory),
    CharEnumField("transType", TransactionType.Algo, TransactionType),
    PacketField("liqAttr", 0, LiqAttr),
    ByteEnumField("lastMkt", LastMkt.DCSE, LastMkt),
    ]
bind_layers(Header, ExecutedOrder, pkgType=PktType.SeqData)

class BrokenReason(bytes, Enum):
    Erroneous = b'E'
    Consent = b'C'
    Supervisory = b'S'
    External = b'X'


class BrokenTradeOrder(Packet):
    name = 'BrokenTradeOrder'
    fields_desc = [
    CharEnumField("msgType", OutMsgType.BrokenTradeOrder, OutMsgType),
    u64("timestamp", 0),
    u32("userRef", 0),
    u32("matchNum", 0),
    CharEnumField("reason", BrokenReason.Erroneous, BrokenReason),
    CharEnumField("tradingMode", TradingMode.OpeningAuction, TradingMode),
    CharEnumField("transCat", TransactionCategory.DarkTrade, TransactionCategory),
    CharEnumField("transType", TransactionType.Algo, TransactionType),
    ]
bind_layers(Header, BrokenTradeOrder, pkgType=PktType.SeqData)

RejectReason = i16;

class RejectedOrder(Packet):
    name = 'RejectedOrder'
    fields_desc = [
    CharEnumField("msgType", OutMsgType.RejectedOrder, OutMsgType),
    u64("timestamp", 0),
    u32("userRef", 0),
    i16("reason", 0),
    ]
bind_layers(Header, RejectedOrder, pkgType=PktType.SeqData)

class RestatedReason(bytes, Enum):
    Refresh = b'R'
    Update = b'P'


class RestatedOrder(Packet):
    name = 'RestatedOrder'
    fields_desc = [
    CharEnumField("msgType", OutMsgType.RestatedOrder, OutMsgType),
    u64("timestamp", 0),
    u32("userRef", 0),
    CharEnumField("reason", RestatedReason.Refresh, RestatedReason),
    u16("appendageLength", 0),
        ConditionalField(PacketListField("appendage", [], OrderRestatedAppendageEntry, length_from=lambda pkt:pkt.appendageLength), lambda pkt:pkt.appendageLength > 0),
    ]
bind_layers(Header, RestatedOrder, pkgType=PktType.SeqData)

